pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    GoodCallee good;

    function setUp() public { c = new airPort(); good = new GoodCallee(); }

    function testFuzz_property(address from, bytes memory tosEncoded) public {
        address[] memory _tos = _decodeAddresses(tosEncoded);
        vm.assume(_tos.length > 0);

        bool ok;
        try c.transfer(from, address(good), _tos, 1) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok);
    }

    function _decodeAddresses(bytes memory b) internal pure returns (address[] memory) {
        if (b.length < 20) {
            address[] memory empty = new address[](0);
            return empty;
        }
        uint count = b.length / 20;
        address[] memory addrs = new address[](count);
        for (uint i = 0; i < count; i++) {
            uint offset = i * 20;
            address a;
            assembly {
                a := div(mload(add(add(b, 0x20), offset)), 0x1000000000000000000000000)
            }
            addrs[i] = a;
        }
        return addrs;
    }
}

